// A Messenger or Instagram webhook entry becomes the common inbound message. Both use the same
// format; the person is keyed by their page- or Instagram-scoped id, and neither shares a phone or
// email. A tapped conversation starter arrives as a postback with the starter's text.
const { profile, channel } = $('Config').first().json;
const out = [];
for (const item of $('Meta Trigger').all()) {
  for (const e of item.json.messaging ?? []) {
    const m = e.message;
    const pb = e.postback;
    if ((!m && !pb) || m?.is_echo || m?.is_deleted) continue;  // echoes of our own replies, deletions
    const attachments = (m?.attachments ?? []).filter((a) => a.type !== 'fallback').map((a) => ({ type: a.type === 'file' ? 'file' : a.type, url: a.payload?.url ?? null }));
    let text = String(m?.text ?? pb?.title ?? '').trim();
    if (m?.is_unsupported) text = '(sent a message type the assistant cannot read)';
    if (!text && attachments.length) text = `(sent ${attachments.map((a) => a.type).join(', ')})`;
    if (!text) continue;
    out.push({ json: {
      profile,
      channel,
      external_user_id: e.sender.id,
      external_message_id: m?.mid ?? pb?.mid ?? `${e.sender.id}:${e.timestamp}`,
      sent_at: new Date(e.timestamp).toISOString(),
      text,
      attachments,
      sender: { display_name: null, username: null, phone: null, email: null },
      address: { user_id: e.sender.id, account_id: e.recipient.id },
    } });
  }
}
return out;

// Lead Ads: a "leadgen" change carries only the lead's id; Get lead reads the answers.
const out = [];
for (const item of $('Meta Trigger').all()) {
  for (const c of item.json.changes ?? []) {
    if (c.field === 'leadgen' && c.value?.leadgen_id) out.push({ json: { leadgen_id: String(c.value.leadgen_id) } });
  }
}
return out;

// A Lead Ads form submission becomes the common inbound message. The answers go into the text for
// the assistant; the name, phone and email are what the person typed into the form, so Ingest
// stores them and finds the person again when they reply on WhatsApp.
const profile = $('Config').first().json.profile;
return $input.all().map((item) => {
  const lead = item.json;
  const answers = Object.fromEntries((lead.field_data ?? []).map((f) => [f.name, (f.values ?? []).join(', ')]));
  const phone = answers.phone_number ? `+${answers.phone_number.replace(/\D/g, '')}` : null;
  const name = answers.full_name?.trim() || null;
  return { json: {
    profile,
    channel: 'lead_ads',
    external_user_id: String(lead.id),
    external_message_id: `lead:${lead.id}`,
    sent_at: new Date(String(lead.created_time).replace(/([+-]\d\d)(\d\d)$/, '$1:$2')).toISOString(),
    text: `(sent the lead form on Facebook: ${Object.entries(answers).map(([k, v]) => `${k}: ${v}`).join('; ')})`,
    attachments: [],
    sender: { name, display_name: name, username: null, phone, email: answers.email?.trim() || null },
    // The first reply goes to this phone on WhatsApp (see Send message).
    address: { leadgen_id: String(lead.id), form_id: lead.form_id ?? null, phone, first_name: name?.split(/\s+/)[0] ?? null },
  } };
});
